u.E("ev-consiglio-di-gabinetto-1983",1983,"agosto 1983","Primo Consiglio di gabinetto","Il Consiglio dei ministri istituisce per la prima volta con delibera formale un Consiglio di gabinetto; la legge 400/1988 lo prevede poi all'art. 6.","istituzione","consiglio-di-gabinetto",119,119)
u.E("ev-legge-n-400-1988-sulla-presidenza-del-consiglio",1988,"23 agosto 1988","Legge n. 400/1988 sulla Presidenza del Consiglio","Disciplina l'attività di Governo, l'ordinamento della Presidenza del Consiglio e la potestà normativa del Governo (decreti-legge, regolamenti).","legge","governo consiglio-dei-ministri presidente-del-consiglio",119,127)
u.E("ev-dlgs-300-1999",1999,"30 luglio 1999","D.lgs. n. 300/1999 sull'organizzazione del Governo","Riordina i ministeri e ne fissa numero e attribuzioni; il numero è stato poi cambiato più volte.","legge","ministri",119,119)
u.E("ev-legge-81-2001-viceministri",2001,"2001","Legge n. 81/2001: i viceministri","Consente di attribuire il titolo di viceministro a non più di dieci sottosegretari con deleghe ampie.","legge","viceministri",125,125)
u.E("ev-dlgs-165-2001",2001,"30 marzo 2001","D.lgs. n. 165/2001 sul pubblico impiego","Raccoglie le norme del d.lgs. 80/1998 sulla separazione tra indirizzo politico e gestione amministrativa.","legge","separazione-politica-amministrazione",127,127)
u.E("ev-sentenze-103-104-2007",2007,"2007","Sentenze n. 103 e 104/2007 sullo spoil system","La Corte costituzionale limita la decadenza automatica dei dirigenti agli incarichi di diretta collaborazione politica.","giurisprudenza","spoil-system",122,122)

